; Unsigned HL16*DE16 -> unsigned32 HL:DE. Same byte/word partials as
; the public signed kernel, without normalization or sign restoration.
; Preserve IX/IY, all alternates and SP. Clobber ordinary AF/BC; no scratch.
.globl _q14_unsigned
_q14_unsigned::
ld a,h
or a,l
jr z,q14u_zero
ld a,d
or a,e
jr nz,q14u_nonzero
q14u_zero:
ld hl,#0
ld de,#0
ret
q14u_nonzero:
; Keep the old byte shortcut: if either magnitude fits a byte, use just
; one unsigned8x16 product. Nonzero magnitudes are guaranteed here.
ld a,h
or a,a
jr z,q14u_byte
ld a,d
or a,a
jr nz,q14u_word
ex de,hl
q14u_byte:
ld a,l
call _word31_u8_nonzero
ex de,hl
ld l,a
ld h,#0
jp q14u_sign
q14u_word:
; a*b = lo8(a)*b + (hi8(a)*b)<<8. The unsigned helper preserves BC/DE.
; Keep hi8(a) in B, then retain the low partial's high byte in C and its
; low word on the real stack while computing the second partial.
ld b,h
ld a,l
call _word31_u8
push hl
ld c,a
ld a,b
call _word31_u8_nonzero
