; E already supplies result byte 0. ADD starts the carry chain at byte 1;
; ADC merges bytes 2/3 before sign restoration. No intermediate precision loss.
ld b,a
pop de
ld a,d
add a,l
ld d,a
ld a,c
adc a,h
ld l,a
ld a,b
adc a,#0
ld h,a
q14u_sign:
ret

